descriptor.templateCss:
.card {
  padding: 12px 14px;
  border-radius: 12px;
  background: #fff;
  border: 1px solid #e6e9ef;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Arial, sans-serif;
}
.hd {
  font: 700 13px Inter, system-ui;
  color: #37474f;
  margin-bottom: 8px;
}
#g {
  display: grid;
  grid-template-columns: repeat(10, 1fr); /* will be overwritten by JS (bins) */
  gap: 6px;
}
.cell {
  width: 100%;
  padding-top: 100%;
  position: relative;
  border-radius: 8px;
  background: #f4f6f8;
}
.cell > i {
  position: absolute;
  inset: 0;
  border-radius: 8px;
}
.l { background: #c8e6c9; }   /* low  */
.m { background: #ffe082; }   /* med  */
.h { background: #ffab91; }   /* high */

.foot {
  margin-top: 8px;
  font: 12px Inter, system-ui;
  color: #607d8b;
}

/* floating tooltip (re-uses global instance if present) */
.sf-tip {
  position: fixed;
  z-index: 9999;
  min-width: 200px;
  max-width: 260px;
  background: #fff;
  border: 1px solid #e6e9ef;
  border-radius: 10px;
  box-shadow: 0 6px 18px rgba(0,0,0,.08);
  padding: 10px 12px;
  pointer-events: none;
}
.sf-tip.hidden { display: none; }
.sf-tip .t-title { font: 700 12px Inter, system-ui; color: #263238; margin-bottom: 6px; }
.sf-tip .t-body  { font: 12px Inter, system-ui; color: #455a64; }
.sf-tip .row { display: flex; justify-content: space-between; gap: 8px; }
.sf-tip .row b { color: #263238; }
.sf-tip .sep { height: 6px; }
.sf-tip .flag { color: #607d8b; margin-top: 2px; }
.sf-tip .meta { color: #90a4ae; margin-top: 6px; font-size: 11px; }

descriptor.controllerScript:
/* Security & Fraud – Single ATM (time-binned heatmap) */
self.onInit = function () {
  var root = self.ctx.$container[0];
  var grid = root.querySelector('#g');
  var foot = root.querySelector('#f');

  // Settings (kept compatible with your roll-up)
  var S = Object.assign({
    debug: false,
    bins: 30,          // number of cells across time window
    anomalyMax: 100,   // set to 1 if anomaly-score is 0..1
    medThresh: 0.40,   // 40% of max → Medium
    highThresh: 0.75   // 75% of max → High
  }, self.ctx.settings || {});

  function log(m, o){ if (S.debug) try { console.log('[sec.fraud.single]', m, o||''); } catch(_){} }

  // Utilities
  function normKey(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9]+/g, '_'); }
  function lastPoint(arr){ return (arr && arr.length) ? arr[arr.length-1] : null; }
  function normAnomaly(v){
    var x = Number(v); if (isNaN(x)) return null;
    return (S.anomalyMax === 1) ? Math.max(0, Math.min(1, x))
                                : Math.max(0, Math.min(1, x / S.anomalyMax));
  }
  function fmt(ts){
    if (!ts && ts!==0) return '—';
    try { return new Date(ts).toISOString().replace('T',' ').slice(0,19); } catch(_){ return String(ts); }
  }
  function ago(ts){
    if (!ts) return '—';
    var d = Math.max(0, Date.now() - ts);
    var s = Math.round(d/1000); if (s < 60) return s+'s ago';
    var m = Math.round(s/60);   if (m < 60) return m+'m ago';
    var h = Math.round(m/60);   return h+'h ago';
  }

  // Tooltip (global, re-used)
  var tip = (function(){
    var el = document.querySelector('.sf-tip-global');
    if (el) return el;
    el = document.createElement('div');
    el.className = 'sf-tip sf-tip-global hidden';
    el.innerHTML = "<div class='t-title'></div><div class='t-body'></div>";
    document.body.appendChild(el);
    return el;
  })();
  var tTitle = tip.querySelector('.t-title');
  var tBody  = tip.querySelector('.t-body');
  var rafId  = 0;
  function showTip(e, title, bodyHtml){
    if (title !== undefined) tTitle.textContent = title || '';
    if (bodyHtml !== undefined) tBody.innerHTML = bodyHtml || '';
    tip.classList.remove('hidden');
    var mx = e.clientX + 12, my = e.clientY + 12;
    var rect = tip.getBoundingClientRect();
    var x = Math.max(8, Math.min(mx, window.innerWidth - rect.width - 8));
    var y = Math.max(8, Math.min(my, window.innerHeight - rect.height - 8));
    if (rafId) cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(function(){ tip.style.left = x+'px'; tip.style.top = y+'px'; });
  }
  function hideTip(){ if (rafId) cancelAnimationFrame(rafId); tip.classList.add('hidden'); }

  // Core: aggregate one device into time bins
  function aggregateSingle() {
    var ds = self.ctx.data || [];
    var series = {
      anomaly: [], tamper: [], malware: [], skimming: []
    };
    var tw = (self.ctx.defaultSubscription && self.ctx.defaultSubscription.subscriptionTimewindow)
             || self.ctx.timewindow || null;
    var start = null, end = null;
    if (tw && tw.startTs && tw.endTs) { start = tw.startTs; end = tw.endTs; }
    else {
      // fallback: infer from min/max ts across series
      ds.forEach(function(s){
        (s.data||[]).forEach(function(p){
          var ts = Array.isArray(p) ? p[0] : (p && p.ts);
          if (ts==null) return;
          if (start==null || ts < start) start = ts;
          if (end==null   || ts > end)   end   = ts;
        });
      });
    }
    if (start==null || end==null || end<=start) {
      return { bins: [], counts: {L:0,M:0,H:0}, total: 0 };
    }

    // Collect series by key
    for (var i=0;i<ds.length;i++){
      var s = ds[i] || {};
      var key = normKey(s.dataKey && (s.dataKey.name || s.dataKey.label));
      var arr = s.data || [];

      if (key === 'anomaly_score') {
        series.anomaly = arr;
      } else if (key === 'tamper_switch') {
        series.tamper = arr;
      } else if (key === 'malware_detected') {
        series.malware = arr;
      } else if (key === 'skimming_suspected') {
        series.skimming = arr;
      }
    }

    // Pre-scan flags to speed lookups
    function toPoints(arr){ 
      var out = []; 
      for (var i=0;i<arr.length;i++){
        var p = arr[i]; 
        out.push({ ts: Array.isArray(p)?p[0]:p.ts, val: Array.isArray(p)?p[1]:(p && (p.value??p.v)) });
      }
      return out;
    }
    var ptsAn = toPoints(series.anomaly);
    var ptsTm = toPoints(series.tamper);
    var ptsMw = toPoints(series.malware);
    var ptsSk = toPoints(series.skimming);

    var N = Math.max(3, S.bins|0 || 30);
    var span = end - start;
    var step = span / N;

    function sampleNearest(pts, tMid){
      // nearest by absolute time (assumes pts sorted)
      var best = null, bd = Infinity;
      for (var i=pts.length-1; i>=0; i--){
        var d = Math.abs(pts[i].ts - tMid);
        if (d < bd){ bd = d; best = pts[i]; }
        if (pts[i].ts < tMid - step) break; // small speed-up
      }
      return best;
    }

    function classify(bucket) {
      // hard flags first
      if (bucket.malwareVal === 1 || bucket.tamperVal === 1 || bucket.skimmingVal === 1) {
        return { cls: 'h', why: 'hard-flag' };
      }
      if (bucket.anomaly01 != null && bucket.anomaly01 >= S.highThresh) return { cls: 'h', why: 'anomaly-high' };
      if (bucket.anomaly01 != null && bucket.anomaly01 >= S.medThresh)  return { cls: 'm', why: 'anomaly-med' };
      return { cls: 'l', why: 'normal' };
    }

    var out = [], cL=0, cM=0, cH=0;

    for (var b=0; b<N; b++){
      var t0 = start + b*step;
      var t1 = start + (b+1)*step;
      var tm = (t0 + t1) / 2;

      var an = sampleNearest(ptsAn, tm);
      var tmpr = sampleNearest(ptsTm, tm);
      var malw = sampleNearest(ptsMw, tm);
      var skim = sampleNearest(ptsSk, tm);

      var bucket = {
        ts: tm,
        anomalyRaw: an ? Number(an.val) : null,
        anomaly01:  an && !isNaN(Number(an.val)) ? normAnomaly(an.val) : null,
        tamperVal:  tmpr ? (Number(tmpr.val)===1?1:0) : 0,
        malwareVal: malw ? (Number(malw.val)===1?1:0) : 0,
        skimmingVal: skim ? (Number(skim.val)===1?1:0) : 0,
        anTs: an && an.ts, tmTs: tmpr && tmpr.ts, mwTs: malw && malw.ts, skTs: skim && skim.ts
      };

      var res = classify(bucket);
      out.push({ cls: res.cls, why: res.why, b: bucket });

      if (res.cls==='l') cL++; else if (res.cls==='m') cM++; else cH++;
    }

    return { bins: out, counts: {L:cL, M:cM, H:cH}, total: N };
  }

  function tipBody(cell){
    var b = cell.b || {};
    var parts = [];
    var risk = (cell.cls==='h' ? 'High' : cell.cls==='m' ? 'Med' : 'Low');
    parts.push("<div class='row'><span>Risk</span><b>"+risk+"</b></div>");

    var an = (b.anomaly01!=null) ? Math.round(b.anomaly01*100)+'%' : '—';
    parts.push("<div class='row'><span>Anomaly</span><b>"+an+"</b></div>");
    parts.push("<div class='sep'></div>");

    var flags = [];
    if (b.skimmingVal===1) flags.push('• Skimming suspected');
    if (b.malwareVal===1)  flags.push('• Malware detected');
    if (b.tamperVal===1)   flags.push('• Tamper switch');
    if (!flags.length)     flags.push('• No hard flags');
    flags.forEach(function(s){ parts.push("<div class='flag'>"+s+"</div>"); });

    var meta = [];
    if (b.anTs) meta.push('anomaly '+ago(b.anTs));
    if (b.skTs) meta.push('skimming '+ago(b.skTs));
    if (b.mwTs) meta.push('malware '+ago(b.mwTs));
    if (b.tmTs) meta.push('tamper '+ago(b.tmTs));
    if (meta.length) parts.push("<div class='meta'>Updated: "+meta.join(' · ')+"</div>");

    return parts.join('');
  }

  function renderAgg(agg){
    var cols = Math.max(3, S.bins|0 || 30);
    grid.style.gridTemplateColumns = 'repeat('+cols+', 1fr)';
    grid.innerHTML = '';

    agg.bins.forEach(function(cell){
      var d = document.createElement('div');
      d.className = 'cell';
      var i = document.createElement('i');
      i.className = cell.cls;
      d.appendChild(i);

      d.setAttribute('role','img');
      d.setAttribute('aria-label', (cell.cls==='h'?'High':cell.cls==='m'?'Medium':'Low') + ' risk at '+fmt(cell.b.ts));

      d.addEventListener('mouseenter', function(e){
        showTip(e, fmt(cell.b.ts), tipBody(cell));
      });
      d.addEventListener('mousemove', function(e){ showTip(e); });
      d.addEventListener('mouseleave', hideTip);

      grid.appendChild(d);
    });

    var N = Math.max(1, agg.total);
    var pct = function(x){ return Math.round((x*100)/N)+'%'; };
    foot.textContent = 'Low '+pct(agg.counts.L)+' · Med '+pct(agg.counts.M)+' · High '+pct(agg.counts.H);
  }

  function update(){
    var agg = aggregateSingle();
    renderAgg(agg);
  }

  update();
  self.onDataUpdated = update;
};

